-- 6.x: the client no longer ships QuestPOIPoint.dbc; the dig site outlines of the research sites come from the 5.4.8 client (18414)
DROP TABLE IF EXISTS `archaeology_site_point`;
CREATE TABLE `archaeology_site_point` (
  `QuestPOIBlobID` int unsigned NOT NULL,
  `Idx` tinyint unsigned NOT NULL,
  `X` int NOT NULL DEFAULT '0',
  `Y` int NOT NULL DEFAULT '0',
  PRIMARY KEY (`QuestPOIBlobID`,`Idx`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
DELETE FROM `archaeology_site_point`;
